    // Runs `operation` on `backend` through the dispatcher (Backend.Name(...)) with arguments as Intercept records them;
    // returns what it returns (null for nothing).
    public static object? Invoke(Backend backend, Operation operation, object?[] a)
    {
        IDisposable? cache = null;
        try
        {
            switch (operation.Index)
            {
                case 0:
